/* TRX-CL 44.1 kHz render (trxcl_render_block_44k1), hand-written SHARC+.
 * Generated by gen_trxcl.py.
 *
 * Bit-exact replacement for the translated render of the original OS 1.63
 * DSP56300 code at P:$102abf-$102b86 (model: trxcl_model.py). It keeps the
 * translated voice layout and the shared scratch contract: every word of
 * voice state, x/y scratch, y:$20 history and the 44.1 kHz block ends as
 * the original leaves it.
 *
 * The oscillators: phase hi:lo (hi & $7fff before each read; lo kept << 8
 * so the add carries), step x1:x0, where the original reads every sample
 * into x0, so after the first step x0 is the previous sine word.
 *  1. Y2 = start delay: x:k = Y8 for its samples, then oscillator 1 (Ya:Yb,
 *     step Y3/2; in the block where the delay ends the step is the number of
 *     samples left, x0 = 0).
 *  2. Oscillator 2 (Yc:Yd, step Y4/2) times Y7, plus x:k, times the envelope
 *     Y9 (decay Y1) / 8 into x:$20+k.
 *  3. Biquad pair Y5/Y6 into x:$42+k; block = x:$40+k.
 *
 * Declines (calls the reference render) when Y2 < 0 or a coefficient table
 * address is outside the source words.
 *
 * Calling convention as the translated renders: R4 = voice, R8 = sine.
 * @SRC@ = byte address of source word 0 (immutable source base - 0x80000).
 * @TMP@ = a 256-word scratch block owned by the hand-written renders.
 */
.EXTERN md_shared_scratch_x.;
.EXTERN md_shared_scratch_y.;
.EXTERN md_shared_y20.;
.EXTERN trxcl_render_block_44k1_c.;
.SECTION/SW seg_swco;
.GLOBAL trxcl_render_block_44k1.;
trxcl_render_block_44k1.:
    I7=MODIFY (I7,-0x34)(NW);
    DM (-3,I6) = R8;
    DM (-4,I6) = R9;
    DM (-5,I6) = R10;
    DM (-6,I6) = R11;
    DM (-7,I6) = R12;
    DM (-8,I6) = R13;
    DM (-9,I6) = R14;
