    R4 = DM (0,I4);
    R1 = 0x140080;
    R1 = R1 + R10;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R5 = DM (0,I4);
    R4 = R4 + R9;
    R5 = R5 + R9;
    R1 = 0x140900;
    R1 = R1 + R4;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R11 = DM (0,I4);
    R1 = 0x141900;
    R1 = R1 + R5;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R12 = DM (0,I4);
    R11 = LSHIFT R11 BY 8;
    R12 = LSHIFT R12 BY 8;
