    R2 = R12 * R1 (SSF);                 /* floor(4*x1*y1 / 2^24) */
    R2 = MIN(R2,R14);
    R2 = MAX(R2,R15);                    /* g */
    R3 = ASHIFT R12 BY R6;               /* y1 */
    R5 = 0;
    MR1F = R5;
    MR0F = R5;                           /* MR = 0 (no MRF = 0 in the translated forms) */
    MRF = MRF - R12 * R3 (SSF);
    R4 = MR1F;                           /* c = lim(-2*y1*y1) */
    R5 = LSHIFT R4 BY 8;
    DM (0,I2) = R5;
    R5 = LSHIFT R2 BY 8;
    DM (1,I2) = R5;
    DM (2,I2) = R4;
    DM (3,I2) = R2;
