    I1 = md_shared_y20.;
    R1 = DM (0,I1);
    R1 = FEXT R1 BY 0:24;
    DM (0,I1) = R1;
    R1 = LSHIFT R1 BY 8;
    R6 = -8;
    R1 = ASHIFT R1 BY R6;
    I1 = md_shared_scratch_y.;
    DM (32,I1) = R1;
    R0 = DM (-28,I6);
    I4 = R0;                            /* sine table */
    R5 = 0x7FFF;
    R12 = -8;
    I1 = md_shared_scratch_x.;
    R1 = DM (0xA,I0);
    R2 = DM (0xB,I0);
    R2 = LSHIFT R2 BY 8;
    R0 = DM (2,I0);
    R0 = PASS R0;
    IF NE JUMP .L_delay;
    R6 = DM (3,I0);
    R3 = LSHIFT R6 BY 31;               /* x0 << 8 = (Y3 & 1) << 31 */
    R7 = -1;
    R4 = ASHIFT R6 BY R7;
    R0 = 32;
    /* (inlined .L_osc) */
    LCNTR = R0 , DO (PC,.L_osc_end_i2)UNTIL LCE;
    R1 = R1 AND R5;
    M4 = R1;
    R0 = DM (M4,I4);
    R2 = R2 + R3;
    R1 = R1 + R4 + CI;
