    R10 = -1;
    R0 = PASS R5;
    DM (0xE,I0) = R0;
    R0 = PASS R6;
    DM (0xF,I0) = R0;
    R0 = PASS R7;
    DM (0x10,I0) = R0;
    R0 = PASS R8;
    DM (0x11,I0) = R0;
    I1 = md_shared_scratch_x.;
    R0 = DM (0xF,I0);
    DM (0,I1) = R0;                     /* x:0/1 = s(30), s(31) */
    R0 = DM (0xE,I0);
    DM (1,I1) = R0;
    R0 = DM (0x3F,I1);
    DM (0x12,I0) = R0;
    R0 = DM (0x3E,I1);
    DM (0x13,I0) = R0;
    /* y:0..3 = c, 1/2, -1, 1/2 */
